import 'dart:convert';

import 'package:flutter/services.dart';

/// Asset folder of the shipped pack (generated by `tool/build_pack.sh`).
const packAssetPrefix = 'packages/content_core/assets/generated/example-core/';

/// Reads the shipped pack from [bundle] as a map of pack-relative path to
/// text, the shape `loadPack` takes.
Future<Map<String, String>> loadPackFiles(AssetBundle bundle) async {
  final manifest = await AssetManifest.loadFromAssetBundle(bundle);
  final files = <String, String>{};
  for (final key in manifest.listAssets()) {
    if (!key.startsWith(packAssetPrefix)) continue;
    files[key.substring(packAssetPrefix.length)] = utf8.decode(
      (await bundle.load(key)).buffer.asUint8List(),
    );
  }
  return files;
}
